}
function memory_check() {
 title "内存使用情况: "
 free -h
}
function cpu_check() {
 title "CPU信息: "
 uptime
}
function check_netstat() {
 title "网络各种链接状态: "
 netstat -n | awk '/^tcp/ {++S[$NF]} END {for(a in S) print a, S[a]}'
}
function kernel_check() {
 title "内核版本: "
 uname -a
 lsb_release -a
}
